previewCss:
.darma-loader-darma-b9-wifi-broadcast { --accent: var(--loader-color, #0284c7); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; }
.darma-loader-darma-b9-wifi-broadcast::after { content: ''; position: absolute; left: 50%; bottom: 14%; width: 9%; height: 9%; transform: translateX(-50%); border-radius: 50%; background: var(--accent); }
.darma-loader-darma-b9-wifi-broadcast span { position: absolute; left: 50%; bottom: 14%; translate: -50% 0; border: calc(var(--loader-size, 84px) * .045) solid var(--accent); border-bottom-color: transparent; border-left-color: transparent; border-right-color: transparent; border-radius: 50%; animation: darma-loader-darma-b9-wifi-broadcast-wifi calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b9-wifi-broadcast span:nth-child(1) { width: 26%; height: 26%; animation-delay: 0s; }
.darma-loader-darma-b9-wifi-broadcast span:nth-child(2) { width: 52%; height: 52%; animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b9-wifi-broadcast span:nth-child(3) { width: 80%; height: 80%; animation-delay: calc(var(--loader-speed, 1s) * .4); }
@keyframes darma-loader-darma-b9-wifi-broadcast-wifi { 0%, 65%, 100% { opacity: .18; } 32% { opacity: 1; } }

